import unittest

from queue_lib.backoff import backoff_ms


class BackoffTests(unittest.TestCase):
    def test_doubles_each_attempt(self):
        self.assertEqual(backoff_ms(0, base_ms=100, max_ms=10_000), 100)
        self.assertEqual(backoff_ms(1, base_ms=100, max_ms=10_000), 200)
        self.assertEqual(backoff_ms(3, base_ms=100, max_ms=10_000), 800)

    def test_caps_at_max(self):
        self.assertEqual(backoff_ms(20, base_ms=100, max_ms=10_000), 10_000)

    def test_negative_attempt_rejected(self):
        with self.assertRaises(ValueError):
            backoff_ms(-1, base_ms=100, max_ms=10_000)

