    assert wrap("the quick brown fox jumps over the lazy dog", 15) == [
        "the quick brown",
        "fox jumps over",
        "the lazy dog",
    ]


def test_lines_fit_unless_single_word_is_too_long():
    text = "a bb ccc dddd eeeee supercalifragilistic ff"
    lines = wrap(text, 8)
    for line in lines:
        if " " in line:
            assert len(line) <= 8
    assert " ".join(lines) == text
